1	// Access token storage using localStorage for persistence across tabs and sessions.
2	// Tokens are cleared on logout or expiry.
3	let accessToken: string | null = null;
4	let tokenExpiresAt: Date | null = null;
5	
6	const TOKEN_KEY = "memos_access_token";
7	const EXPIRES_KEY = "memos_token_expires_at";
8	
9	// BroadcastChannel lets tabs share freshly-refreshed tokens so that only one
10	// tab needs to hit the refresh endpoint. When another tab successfully refreshes
11	// we adopt the new token immediately, avoiding a redundant (and potentially
12	// conflicting) refresh request of our own.
13	const TOKEN_CHANNEL_NAME = "memos_token_sync";
14	
15	// Token refresh policy:
16	// - REQUEST_TOKEN_EXPIRY_BUFFER_MS: used for normal API requests.
17	// - FOCUS_TOKEN_EXPIRY_BUFFER_MS: used on tab visibility restore to refresh earlier.
18	export const REQUEST_TOKEN_EXPIRY_BUFFER_MS = 30 * 1000;
19	export const FOCUS_TOKEN_EXPIRY_BUFFER_MS = 2 * 60 * 1000;
20	
21	interface TokenBroadcastMessage {
22	  token: string;
23	  expiresAt: string; // ISO string
24	}
25	
26	let tokenChannel: BroadcastChannel | null = null;
27	
28	function getTokenChannel(): BroadcastChannel | null {
29	  if (tokenChannel) return tokenChannel;
30	  try {
31	    tokenChannel = new BroadcastChannel(TOKEN_CHANNEL_NAME);
32	    tokenChannel.onmessage = (event: MessageEvent<TokenBroadcastMessage>) => {
33	      const { token, expiresAt } = event.data ?? {};
34	      if (token && expiresAt) {
35	        // Another tab refreshed — adopt the token in-memory so we don't
36	        // fire our own refresh request.
37	        accessToken = token;
38	        tokenExpiresAt = new Date(expiresAt);
39	      }
40	    };
41	  } catch {
42	    // BroadcastChannel not available (e.g. some privacy modes)
43	    tokenChannel = null;
44	  }
45	  return tokenChannel;
46	}
47	
48	// Initialize the channel at module load so the listener is registered
49	// before any token refresh can occur in any tab.
50	getTokenChannel();
51	
52	export const getAccessToken = (): string | null => {
53	  if (!accessToken) {
54	    try {
55	      const storedToken = localStorage.getItem(TOKEN_KEY);
56	      const storedExpires = localStorage.getItem(EXPIRES_KEY);
57	
58	      if (storedToken && storedExpires) {
59	        const expiresAt = new Date(storedExpires);
60	        if (expiresAt > new Date()) {
61	          accessToken = storedToken;
62	          tokenExpiresAt = expiresAt;
63	        }
64	        // Do NOT remove expired tokens here. getRequestToken() in connect.ts calls
65	        // hasStoredToken() to decide whether to attempt a refresh — if we eagerly delete
66	        // the expired token, it returns null immediately, skipping the refresh and sending
67	        // the request without credentials.
68	        // clearAccessToken() handles proper cleanup after a confirmed auth failure or logout.
69	      }
70	    } catch (e) {
71	      // localStorage might not be available (e.g., in some privacy modes)
72	      console.warn("Failed to access localStorage:", e);
73	    }
74	  }
75	  return accessToken;
76	};
77	
78	export const setAccessToken = (token: string | null, expiresAt?: Date): void => {
79	  accessToken = token;
80	  tokenExpiresAt = expiresAt || null;
81	
82	  try {
83	    if (token && expiresAt) {
84	      localStorage.setItem(TOKEN_KEY, token);
85	      localStorage.setItem(EXPIRES_KEY, expiresAt.toISOString());
86	      // Broadcast to other tabs so they adopt the new token without refreshing.
87	      const msg: TokenBroadcastMessage = { token, expiresAt: expiresAt.toISOString() };
88	      getTokenChannel()?.postMessage(msg);
89	    } else {
90	      localStorage.removeItem(TOKEN_KEY);
91	      localStorage.removeItem(EXPIRES_KEY);
92	    }
93	  } catch (e) {
94	    // localStorage might not be available (e.g., in some privacy modes)
95	    console.warn("Failed to write to localStorage:", e);
96	  }
97	};
98	
99	export const isTokenExpired = (bufferMs: number = REQUEST_TOKEN_EXPIRY_BUFFER_MS): boolean => {
100	  if (!tokenExpiresAt) return true;
101	  // Consider expired with a safety buffer before actual expiry.
102	  return new Date() >= new Date(tokenExpiresAt.getTime() - bufferMs);
103	};
104	
105	// Returns true if a token exists in localStorage, even if it is expired.
106	// Used to decide whether to attempt GetCurrentUser on app init — if no token
107	// was ever stored, the user is definitively not logged in and there is nothing
108	// to refresh, so we can skip the network round-trip entirely.
109	export const hasStoredToken = (): boolean => {
110	  if (accessToken) return true;
111	  try {
112	    return !!localStorage.getItem(TOKEN_KEY);
113	  } catch {
114	    return false;
115	  }
116	};
117	
118	export const clearAccessToken = (): void => {
119	  accessToken = null;
120	  tokenExpiresAt = null;
121	
122	  try {
123	    localStorage.removeItem(TOKEN_KEY);
124	    localStorage.removeItem(EXPIRES_KEY);
125	  } catch (e) {
126	    console.warn("Failed to clear localStorage:", e);
127	  }
128	};
